fn validate_target_size(target_size: &str) -> bool {
    let parts: Vec<&str> = target_size.split('x').collect();
    if parts.len() != 2 {
        return false;
    }
    parts.iter().all(|&part| part.parse::<u32>().is_ok())
}

fn main() {
    assert!(validate_target_size("500x500"));
    assert!(!validate_target_size("500x"));
    assert!(!validate_target_size("x500"));
    assert!(!validate_target_size("500500"));
    assert!(!validate_target_size("abcxdef"));
}
